import React from "react";

/* Avatar cropped from the reference image */
const AVATAR = "data:image/png;base64,";

const AXONIX = "data:image/png;base64,";

/* ---------- Card visuals ---------- */

function Dial() {
  const ticks = Array.from({ length: 60 }, (_, i) => i);
  return (
    <svg viewBox="0 0 200 200" className="of-dial">
      <defs>
        <radialGradient id="of-disc" cx="50%" cy="45%" r="55%">
          <stop offset="0%" stopColor="#f8f8f8" />
          <stop offset="100%" stopColor="#ebebeb" />
        </radialGradient>
        <filter id="of-inner" x="-20%" y="-20%" width="140%" height="150%">
          <feDropShadow dx="0" dy="3" stdDeviation="4" floodColor="#000" floodOpacity="0.1" />
        </filter>
      </defs>

      {/* outer disc */}
      <circle cx="100" cy="100" r="89" fill="url(#of-disc)" />

      {/* ticks: 12 major (every 30deg) + 4 minor between each */}
      {ticks.map((i) => {
        const major = i % 5 === 0;
        return (
          <line
            key={i}
            x1="100" y1={major ? 23 : 23.5} x2="100" y2={major ? 32 : 27.5}
            stroke={major ? "#161616" : "#2a2a2a"}
            strokeWidth={major ? 3.2 : 1.3}
            strokeLinecap="round"
            transform={`rotate(${i * 6} 100 100)`}
          />
        );
      })}

      {/* black progress arc: from 12 o'clock, ~147deg clockwise */}
      <circle
        cx="100" cy="100" r="87.4" fill="none" stroke="#141414" strokeWidth="6.6"
        strokeLinecap="round" strokeDasharray="224.2 549.2"
        transform="rotate(-90 100 100)"
      />
      <circle cx="147.6" cy="173.3" r="3.4" fill="#141414" stroke="#fff" strokeWidth="1.6" />

      {/* inner white disc */}
      <circle cx="100" cy="100" r="55.8" fill="#fdfdfd" filter="url(#of-inner)" />

      {/* bar-chart + line icon (from reference) */}
      <svg x="80" y="82" width="40" height="37" viewBox="8 8 36 33">
        <g fill="#111">
          <rect x="9" y="29" width="5" height="10" rx="0.8" />
          <rect x="18" y="21.5" width="5.5" height="17.5" rx="0.8" />
          <rect x="27" y="25.5" width="5.5" height="13.5" rx="0.8" />
          <rect x="36.5" y="20" width="5.5" height="19" rx="0.8" />
        </g>
        <polyline points="11.5,20.5 20.8,12.8 29.7,16.5 39.3,10.8" fill="none" stroke="#111" strokeWidth="1.4" strokeLinejoin="round" strokeLinecap="round" />
        <g fill="#111">
          <circle cx="11.5" cy="20.5" r="2.4" /><circle cx="20.8" cy="12.8" r="2.4" />
          <circle cx="29.7" cy="16.5" r="2.4" /><circle cx="39.3" cy="10.8" r="2.4" />
        </g>
      </svg>
    </svg>
  );
}

function Growth() {
  // [x, light(y1,y2), mid(y1,y2), black(y1,y2)] in a 750x690 box taken from the reference
  const bars = [
    [92, [110, 185], [210, 345], [368, 638]],
    [203, [288, 335], [355, 440], [460, 638]],
    [315, [240, 295], [318, 415], [437, 638]],
    [427, [160, 228], [250, 372], [395, 638]],
    [538, [288, 335], [355, 440], [460, 638]],
    [649, [40, 125], [152, 305], [332, 638]],
  ] as const;
  const tiers = ["#d8d8d8", "#8d8d8d", "#141414"];
  return (
    <div className="of-growth">
      <span className="of-pill" style={{ left: 10, top: 46 }}>20% Automation</span>
      <span className="of-pill" style={{ right: 6, top: 8 }}>99% Autorized</span>
      <span className="of-pill of-pill-sm" style={{ left: 0, top: 108 }}>+12.8%</span>
      <div className="of-big">3.18K</div>
      <svg className="of-bars" viewBox="68 36 606 606" width="100" height="100">
        {bars.map(([x, ...segs]) =>
          segs.map(([y1, y2], t) => (
            <rect key={x + "-" + t} x={x - 22} y={y1} width="44" height={y2 - y1} rx="22" fill={tiers[t]} />
          ))
        )}
      </svg>
    </div>
  );
}

function Chat() {
  return (
    <div className="of-chat">
      <div className="of-row of-row-first">
        <img className="of-avatar of-avatar-img" alt="Ash Gley" src={AVATAR} />
        <div>
          <div className="of-name">Ash Gley</div>
          <div className="of-bubble">Give me the total profit for this week</div>
        </div>
      </div>
      <div className="of-row" style={{ marginTop: 14 }}>
        <img className="of-avatar of-avatar-img" alt="Axonix" src={AXONIX} />
        <div>
          <div className="of-name">Axonix</div>
          <div className="of-bubble">
            Okay according to your request,<br />
            I will make a profit recap for this week.<br />
            Just a moment...
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------- Section ---------- */

const CARDS = [
  { visual: <Dial />, title: "Real-Time Analytics", text: "Stay ahead with accurate, real-time performance tracking." },
  { visual: <Growth />, title: "AI-Driven Growth", text: "Make smarter moves with accurate, real-time business insights." },
  { visual: <Chat />, title: "Superfast AI response", text: "Discover how AI can enhance every aspect of your web design workflow." },
];

export function AgencySection() {
  return (
    <section className="of-section">
      <style>{css}</style>

      <div className="of-head">
        <span className="of-badge">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#111" strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round">
            <circle cx="15" cy="15" r="6" />
            <path d="M8.2 3.8 L13.4 12.6 Q13.9 13.4 13 13.4 L3.4 13.4 Q2.5 13.4 3 12.6 L7.2 3.8 Q7.7 3 8.2 3.8 Z" fill="#fff" />
          </svg>
          OUR FEATURES
        </span>
        <h2>
          Partner with an AI agency<br />
          <strong>delivering smart solutions.</strong>
        </h2>
        <p>
          We've partnered with companies in finance, healthcare, e-commerce and more
          <br className="of-br" />
          {" "}to deliver transformative AI solutions.
        </p>
      </div>

      <div className="of-grid">
        {CARDS.map((c) => (
          <article className="of-card feature-hover-card" key={c.title} tabIndex={0}>
            <div className="of-card-in feature-hover-card-inner">
              <div className="of-visual">{c.visual}</div>
              <h3>{c.title}</h3>
              <p>{c.text}</p>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

